                    // the pen strokes over a signature line in the text-free render (P8.3): no request, no view; the groups are written with the seals'
                    Sigpx.SpFind(i + 1, views, nview, rules, owords, etext, emon.Port.BmsGet(bms, nid), pgw, s5, s6);
                    Sigpx.SpRecord(i, s5, cg);
                }
            }
        }
        // a page in a script the engine has no model for (D564): the page's mask says so, and `sc-tag-unread` holds what OCR won of it at a low confidence
        if (Scriptcheck.SkUnread(ans, ao, s6) == 1) {
            emon.Port.CellsSet(mask, i, Scan.ScMaskUnread());
        }
        return Plan.UsDone();
    }
    internal static int PuScanPixels(int i, int did, int oid, int ao, int pxw, int pxh, int dpi100, emon.Port.Cells ans, emon.Port.Cells rq, emon.Port.Cells loc, emon.Port.BitmapSet bms, int fuse, emon.Port.Cells rtp, emon.Port.Cells s6) {
        // D564: 0 when the raster of the page unit is the bitmap under `did`; the factor `k` (2 to 4) when the first pass `ao` of it (the OCR request `oid`) shows
        // that the raster is too small for the engine to read (`emon.upscale`) and the pixels are there to enlarge: the enlarged raster is then made as a kin-made view
        // (`rv-upscaled`) and its OCR is asked for (`ri-upscale`, naming the view's pixel hash). Answers -1 when it has asked (the caller answers `us-requests`).
        if (PuPx(bms, did, fuse) == 0) {
            return 0;
        }
        int k = Upscale.UpFactor(ans, ao, pxw, pxh, s6);
        int uvid = Plan.PuViewId(i, Upscale.RvUpscaled());
        int uid = Plan.PuId(i, Upscale.RiUpscale());
        if (k < 2) {
            return 0;
        }
        if (Plan.AnFind(ans, uid) < 0) {
            Upscale.UpMake(bms, uvid, Plan.PuViewId(i, Upscale.RvUpscaleTmp()), emon.Port.BmsGet(bms, did), k, s6);
            emon.Port.BitmapHash(emon.Port.BmsGet(bms, uvid), rtp, Retarget.RtpHash());
            Scan.ScRequestView(rq, uid, uvid, emon.Port.CellsAt(rtp, Retarget.RtpHash()), emon.Port.CellsAt(rtp, Retarget.RtpHash() + 1), Upscale.UpHint(ans, ao, k, dpi100, s6), loc);
            return -1;
        }
        return k;
    }
    public static int PuScanCore(int i, int input, int fuse, int did, int ad, int dpi100, int obj, int bx0, int by0, int bx1, int by1, int pw, int ph, int maskv, int seals, emon.Port.Cells ans, emon.Port.Cells rq, emon.Port.Cells loc, emon.Port.BitmapSet bms, emon.Port.Cells mask, emon.Port.Cells scr, emon.Port.Cells epages, emon.Port.Cells views, emon.Port.Cells etext, emon.Port.Cells feats, emon.Port.Cells images, emon.Port.Cells oruns, emon.Port.Cells oblocks, emon.Port.Cells olines, emon.Port.Cells owords, emon.Port.Cells osyms, emon.Port.Cells oalts, emon.Port.Cells words, emon.Port.Cells lines, emon.Port.Cells refs, emon.Port.Cells tlines, emon.Port.Cells cg, emon.Port.Cells inks, emon.Port.Cells comps, emon.Port.Cells rules, emon.Port.Cells prims, emon.Port.Cells tpts, emon.Port.Cells ws, emon.Port.Cells sv, emon.Port.Cells aux, emon.Port.Cells snap, emon.Port.Cells rtp, emon.Port.Cells rn, emon.Port.Cells ri, emon.Port.Cells cs, emon.Port.Cells vr, emon.Port.Cells pc, emon.Port.Cells sg, emon.Port.Cells mem, emon.Port.Cells s1, emon.Port.Cells s2, emon.Port.Cells s3, emon.Port.Cells s4, emon.Port.Cells s5, emon.Port.Cells s6, emon.Port.Cells ofz, emon.Port.Cells oaz) {
        // A SCANNED page whose raster is in (the decode or the render under `did`, its answer at `ad`; `dpi100` its resolution, `obj` the image's object, the page
        // region it shows is (`bx0` `by0`)-(`bx1` `by1`) of a page `pw` x `ph`, all centipoints): the OCR of the bitmap, the ink layers of the bitmap and the
        // targeted passes they and the first pass call for, then the lines the pipeline reads (`rt-adopt`). With no pixel in the decode answer (a transcript recorded
        // slim) the page is what it always was: the first pass's lines. `maskv` is what the page's `mask` cell becomes (1 an image page, 2 a PDF's scanned page);
        // `seals` 1 looks for seals and signatures in the pixels (PDF pages and image frames); 0 skips those stages.
        // D564: a raster the first pass shows to be too small is read again enlarged (`pu-scan-pixels`) and that reading, when it reads as much, is the first pass.
        int oid = Plan.PuId(i, Plan.PiOcr());
        int uid = Plan.PuId(i, Upscale.RiUpscale());
        int uvid = Plan.PuViewId(i, Upscale.RvUpscaled());
        int rid = did;
        int roid = oid;
        int pxw = 0;
        int pxh = 0;
        int rdpi = dpi100;
        int hint = 0;
        int mv = maskv;
        int ao = -1;
        int ua = -1;
        int k = 0;
        int vdec = 0;
        int l0 = 0;
        int w0 = 0;
        int nw = 0;
        int run = 0;
        int nl = 0;
        int rotmed = 0;
        int asked = 0;
        int nsel = 0;
        pxw = Plan.AnArg(ans, ad, 0);
        pxh = Plan.AnArg(ans, ad, 1);
        ao = Plan.AnFind(ans, oid);
        if (ao < 0) {
            Scan.ScRequest(rq, oid, did, (dpi100 + 50) / 100, loc);
            return Plan.UsRequests();
        }
        if (Plan.AnOk(ans, ao) != 1) {
            return Plan.UsDone();
        }
        if (PuDry(fuse) == 1) {
            return Plan.UsDone();
        }
        ua = Scriptcheck.SkRoute(ans, ao, Plan.PuId(i, 28), did, (dpi100 + 50) / 100, rq, s6);
        if (ua < 0) {
            return Plan.UsRequests();
        }
        if (ua != ao) {
            roid = Plan.PuId(i, 28);
        }
        ao = ua;
        Retarget.RtPrep(rtp);
        // a page in a script the engine has no model for (D564): the first pass is junk at a confidence it should not have; `sc-tag` says so
        if (Scriptcheck.SkUnread(ans, ao, s6) == 1) {
            mv += Scan.ScMaskUnread();
